macro variant*(name: static string, body: untyped): untyped =
  result = newStmtList()
  let typeDef = parseStmt("type " & name & " = object")[0]
  var recList = newNimNode(nnkRecList)
  recList.add newIdentDefs(ident("kind"), ident("string"), newEmptyNode())
  for branch in body:
    if branch.kind == nnkCommand:
      let tag = $branch[0]
      let fields = branch[1]
      var branchRec = newNimNode(nnkRecList)
      for f in fields:
        branchRec.add f
      let whenBranch = newNimNode(nnkWhenBranch).add(
        newCall("==", ident("kind"), newLit(tag)),
        branchRec
      )
      recList.add whenBranch
  typeDef[0][2][2] = recList
  result.add typeDef

