macro apiRouter*(routerName: untyped, body: untyped): untyped =
  var caseStmt = newTree(nnkCaseStmt, ident("path"))

  for route in body:
    if route.kind == nnkInfix and route[0].strVal == "->":
      let methodCall = route[1]
      if methodCall.kind == nnkCommand:
        let httpMethod = methodCall[0].strVal
        let routePath = methodCall[1].strVal
        let handlerProc = route[2]

        let branch = newTree(nnkOfBranch, newLit(routePath))
        branch.add quote do:
          return `handlerProc`(req)
        caseStmt.add branch

  let elseBranch = newTree(nnkElse, quote do:
    return "404 Not Found"
  )
  caseStmt.add elseBranch

  result = quote do:
    proc `routerName`(methodName: string, path: string, req: string): string =
      `caseStmt`

