macro configSchema*(name: untyped, body: untyped): untyped =
  let objDef = newTree(nnkTypeSection,
    newTree(nnkTypeDef, name, newEmptyNode(),
      newTree(nnkObjectTy, newEmptyNode(), newEmptyNode(), newTree(nnkRecList))
    )
  )
  let recList = objDef[0][2][2]

  var initBody = newStmtList()
  let resIdent = ident("result")

  for field in body:
    if field.kind == nnkCall:
      let fName = field[0]
      let fType = field[1][0]
      let defaultVal = field[1][1]

      recList.add newIdentDefs(fName, fType)
      initBody.add quote do:
        `resIdent`.`fName` = `defaultVal`

  let initProcName = ident("init" & $name)
  let initProc = quote do:
    proc `initProcName`(): `name` =
      `initBody`

  result = newStmtList(objDef, initProc)

