macro ormModel*(tableName: untyped, body: untyped): untyped =
  result = newStmtList()
  var sqlStr = "CREATE TABLE " & $tableName & " ("

  let objDef = newTree(nnkTypeSection,
    newTree(nnkTypeDef, tableName, newEmptyNode(),
      newTree(nnkObjectTy, newEmptyNode(), newEmptyNode(), newTree(nnkRecList))
    )
  )
  let recList = objDef[0][2][2]

  var cols = newSeq[string]()

  for field in body:
    if field.kind == nnkCall:
      let fName = field[0]
      let fType = field[1][0]
      let sqlMod = field[1][1].strVal

      recList.add newIdentDefs(fName, fType)
      cols.add($fName & " " & sqlMod)

