macro ruleEngine*(engineName: untyped, body: untyped): untyped =
  result = newStmtList()
  var evalBody = newStmtList()

  for rule in body:
    if rule.kind == nnkCall and rule[0].strVal == "rule":
      let ruleBlock = rule[1]
      var condNode = newEmptyNode()
      var actNode = newEmptyNode()

      for part in ruleBlock:
        if part.kind == nnkCall and part[0].strVal == "cond":
          condNode = part[1]
        elif part.kind == nnkCall and part[0].strVal == "act":
          actNode = part[1]

      if condNode.kind != nnkEmpty and actNode.kind != nnkEmpty:
        evalBody.add quote do:
          if `condNode`:
            `actNode`

  result.add quote do:
    proc `engineName`*(fact: int) =
      `evalBody`

