macro xml*(body: untyped): untyped =
  var res = newStmtList()
  let xmlVar = genSym(nskVar, "xmlOut")
  res.add quote do: var `xmlVar` = ""

  proc processXml(n: NimNode) =
    if n.kind == nnkCall:
      let tag = n[0].strVal
      var attrs = ""
      var children = newSeq[NimNode]()

      for i in 1..<n.len:
        if n[i].kind == nnkExprEqExpr:
          attrs.add(" " & n[i][0].strVal & "=\"" & n[i][1].strVal & "\"")
        elif n[i].kind == nnkStmtList:
          for c in n[i]: children.add c

      res.add quote do: `xmlVar`.add("<" & `tag` & `attrs` & ">")
      for c in children: processXml(c)
      res.add quote do: `xmlVar`.add("</" & `tag` & ">")
    elif n.kind in {nnkStrLit, nnkRStrLit}:
      let text = n.strVal
      res.add quote do: `xmlVar`.add(`text`)

  for n in body: processXml(n)
  res.add quote do: `xmlVar`
  return res

