macro pipeline*(name: untyped, body: untyped): untyped =
  var logic = newStmtList()
  let resIdent = ident("result")

  for step in body:
    if step.kind == nnkIdent:
      let op = step.strVal
      if op == "trim":
        logic.add quote do: `resIdent` = strutils.strip(`resIdent`)
      elif op == "toLower":
        logic.add quote do: `resIdent` = strutils.toLowerAscii(`resIdent`)
    elif step.kind == nnkCall:
      let op = step[0].strVal
      if op == "checkLength":
        let length = step[1][0]
        logic.add quote do:
          if `resIdent`.len < `length`: return "ERROR: Too short"

  result = quote do:
    proc `name`*(input: string): string =
      result = input
      `logic`

