macro defineRoles*(body: untyped): untyped =
  var caseStmt = newTree(nnkCaseStmt, ident("role"))

  for node in body:
    if node.kind == nnkCall:
      let roleName = node[0].strVal
      var perms = newSeq[string]()

      if node[1][0].kind == nnkCommand and node[1][0][0].strVal == "can":
        for i in 1..<node[1][0].len:
          perms.add node[1][0][i].strVal

      let branch = newTree(nnkOfBranch, newLit(roleName))
      var checks = newStmtList()
      for p in perms:
        checks.add quote do:
          if action == `p`: return true
      checks.add quote do: return false

      branch.add checks
      caseStmt.add branch

  caseStmt.add newTree(nnkElse, quote do: return false)

  result = quote do:
    proc hasPermission*(role, action: string): bool =
      `caseStmt`

