proc instrumentYields(node: NimNode): NimNode =
  if node.kind == nnkYieldStmt:
    let yieldExpr = node[0]
    return quote do:
      echo "--> Yielding value: ", `yieldExpr`
      yield `yieldExpr`
      echo "<-- Resumed after yield"
  else:
    var res = copyNimNode(node)
    for child in node:
      res.add instrumentYields(child)
    return res

