proc injectDivCheck(node: NimNode): NimNode =
  if node.kind == nnkInfix and (node[0].strVal == "/" or node[0].strVal == "div"):
    let lhs = injectDivCheck(node[1])
    let rhs = injectDivCheck(node[2])
    let op = node[0]
    return quote do:
      block:
        let r = `rhs`
        if r == 0: raise newException(DivByZeroDefect, "Division by zero intercepted by macro!")
        `lhs` `op` r
  else:
    var res = copyNimNode(node)
    for child in node:
      res.add injectDivCheck(child)
    return res

