proc wrapInTry(node: NimNode): NimNode =
  if node.kind == nnkStmtList:
    var res = newStmtList()
    for child in node:
      if child.kind in {nnkCall, nnkCommand}:
        res.add quote do:
          try:
            `child`
          except CatchableError:
            discard
      else:
        res.add wrapInTry(child)
    return res
  else:
    var res = copyNimNode(node)
    for child in node:
      res.add wrapInTry(child)
    return res

