proc injectDefers(node: NimNode): NimNode =
  if node.kind == nnkStmtList:
    var res = newStmtList()
    for child in node:
      res.add injectDefers(child)
      if child.kind in {nnkVarSection, nnkLetSection}:
        let decl = child[0]
        if decl[2].kind == nnkCall and decl[2][0].strVal == "open":
          let varName = decl[0]
          res.add quote do:
            defer: `varName`.close()
    return res
  else:
    var res = copyNimNode(node)
    for child in node:
      res.add injectDefers(child)
    return res

