proc evalMath(expr: string): int =
  let parts = expr.split(" ")
  if parts.len == 3:
    let a = parseInt(parts[0])
    let b = parseInt(parts[2])
    if parts[1] == "+": return a + b
    if parts[1] == "*": return a * b
  return 0

