macro uniqueEnums*(vals: varargs[untyped]): untyped =
  var seen = newSeq[string]()
  var arrayAst = newTree(nnkBracket)

  for v in vals:
    let name = v.strVal
    for s in seen:
      if s == name:
        error("Duplicate enum value found: " & name, v)
    seen.add name
    arrayAst.add v

  result = quote do:
    @`arrayAst`

