macro packStruct*(name: untyped, body: untyped): untyped =
  let typeSec = newTree(nnkTypeSection,
    newTree(nnkTypeDef, name, newEmptyNode(),
      newTree(nnkObjectTy, newEmptyNode(), newEmptyNode(), newTree(nnkRecList))
    )
  )
  let recList = typeSec[0][2][2]

  # In a real scenario, we'd sort these by size. Here we just gather them.
  for decl in body:
    if decl.kind in {nnkVarSection, nnkLetSection}:
      for def in decl:
        recList.add newIdentDefs(def[0], def[1])

  result = typeSec

