macro singleton*(body: untyped): untyped =
  body.expectKind(nnkTypeSection)
  let typeName = body[0][0]

  let instVar = genSym(nskVar, "instance")
  let initFlag = genSym(nskVar, "initialized")

  let code = quote do:
