proc simplifyMath(node: NimNode): NimNode =
  if node.kind == nnkInfix and node[0].strVal == "*":
    if node[2].kind == nnkIntLit and node[2].intVal == 0:
      return newLit(0)
    if node[2].kind == nnkIntLit and node[2].intVal == 1:
      return simplifyMath(node[1])

  var res = copyNimNode(node)
  for child in node:
    res.add simplifyMath(child)
  return res

macro optimizeMath*(body: untyped): untyped =
  result = simplifyMath(body)

