macro unpackDeep*(body: untyped): untyped =
  result = newStmtList()

  for stmt in body:
    if stmt.kind == nnkLetSection and stmt[0][0].kind == nnkTupleConstr:
      let left = stmt[0][0]
      let right = stmt[0][2]
      let tmp = genSym(nskLet, "tmp")

      result.add quote do: let `tmp` = `right`

      for i in 0..<left.len:
        let field = left[i]
        result.add quote do: let `field` = `tmp`[`i`]
    else:
      result.add stmt

when isMainModule:
