proc rewriteAdd(node: NimNode): NimNode =
  if node.kind == nnkInfix and node[0].strVal == "+":
    let lhs = rewriteAdd(node[1])
    let rhs = rewriteAdd(node[2])
    return quote do:
      block:
        let l = `lhs`
        let r = `rhs`
        echo "Adding ", l, " and ", r
        l + r
  else:
    var res = copyNimNode(node)
    for child in node:
      res.add rewriteAdd(child)
    return res

macro logAdditions*(body: untyped): untyped =
  result = rewriteAdd(body)

